// src/pages/FarmMap.jsx
import { useRef, useState, useEffect } from "react";
import C from "../constants/colors";
import S from "../utils/storage";
import { CROPS_ALL } from "../constants/crops";
import Card from "../components/ui/Card";
import Badge from "../components/ui/Badge";
import Input from "../components/ui/Input";
import Btn from "../components/ui/Btn";

function FarmMap({ user, t }) {
  const mapRef      = useRef(null);
  const mapInstance = useRef(null);
  const [loaded,   setLoaded]   = useState(false);
  const [farms,    setFarms]    = useState((user?.farms) || []);
  const [addMode,  setAddMode]  = useState(false);
  const [formFarm, setFormFarm] = useState({ name: "", crop: "", size: "", soilType: "Red", status: "Healthy" });

  // ── Translated strings ──────────────────────────────────────────────────────
  const TX = {
    title:       t("map.title")     || "Farm Map",
    subtitle:    t("map.subtitle")  || "GPS mapping of your farm plots",
    addPlot:     t("map.addPlot")   || "+ Add Farm",
    yourFarms:   t("map.yourFarms") || "My Farm Plots",
    noFarms:     t("map.noFarms")   || "No farms added yet",
    addFirst:    t("map.addFirst")  || "Click '+ Add Farm' to start",
    area:        t("map.area")      || "Area",
    crop:        t("map.crop")      || "Crop",
    plotName:    t("map.plotName")  || "Plot Name",
    // Status labels
    healthy:     t("common.yes")    || "Healthy",
    diseaseAlert:"Disease Alert",
    monitor:     "Monitor",
    // Field condition labels
    fieldConds:  "🌡️ Field Conditions Today",
    temperature: "Temperature",
    humidity:    "Humidity",
    pestRisk:    "Pest Risk",
    diseaseRisk: "Disease Risk",
    irrigation:  "Irrigation Need",
    // Satellite
    ndvi:        "📡 NDVI Satellite Status",
    // Map loading
    loading:     t("common.loading") || "Loading map…",
    // Add farm form
    farmName:    "Farm Name",
    size:        "Size (Acres)",
    soilType:    "Soil Type",
    status:      "Current Status",
    saveFarm:    t("save") || "Save Farm",
    cancel:      t("cancel") || "Cancel",
    clickTip:    "💡 Tip: Click on the map to place your farm at the exact location",
    clickMode:   "📌 Click map to place farm",
  };

  useEffect(() => {
    // Load Leaflet dynamically
    if (document.querySelector("#leaflet-css")) { setLoaded(true); return; }
    const css = document.createElement("link");
    css.id   = "leaflet-css";
    css.rel  = "stylesheet";
    css.href = "https://unpkg.com/leaflet@1.9.4/dist/leaflet.css";
    document.head.appendChild(css);

    const script   = document.createElement("script");
    script.src     = "https://unpkg.com/leaflet@1.9.4/dist/leaflet.js";
    script.onload  = () => setLoaded(true);
    document.head.appendChild(script);
  }, []);

  useEffect(() => {
    if (!loaded || !mapRef.current || mapInstance.current) return;
    const L   = window.L;
    const lat = user.lat || 9.9252;
    const lon = user.lon || 78.1198;

    const map = L.map(mapRef.current, { zoomControl: true }).setView([lat, lon], 13);
    L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png", {
      attribution: "© OpenStreetMap contributors",
    }).addTo(map);

    // User marker
    const icon = L.divIcon({
      html: `<div style="background:${C.bg2};width:14px;height:14px;border-radius:50%;border:3px solid white;box-shadow:0 2px 6px rgba(0,0,0,0.4)"></div>`,
      iconSize: [20, 20], iconAnchor: [10, 10],
    });
    L.marker([lat, lon], { icon })
      .addTo(map)
      .bindPopup(`<b>📍 ${user.name}</b><br>${user.district}, Tamil Nadu<br>${TX.area}: ${user.landSize || "?"} acres`);

    // Farm markers
    farms.forEach(farm => {
      if (farm.lat && farm.lon) addFarmMarker(L, map, farm);
    });

    // Click to place farm
    map.on("click", e => {
      setFormFarm(p => ({ ...p, clickedLat: e.latlng.lat, clickedLon: e.latlng.lng }));
    });

    mapInstance.current = map;
  }, [loaded]);

  const addFarmMarker = (L, map, farm) => {
    const fc = farm.status === "Healthy" ? "#1a7a3a" : farm.status === "Disease Alert" ? "#b83232" : "#c87010";
    const fi = L.divIcon({
      html: `<div style="background:${fc};color:#fff;padding:4px 8px;border-radius:6px;font-size:11px;font-weight:600;white-space:nowrap;box-shadow:0 2px 6px rgba(0,0,0,0.3)">${farm.crop}</div>`,
      className: "",
    });
    L.marker([farm.lat, farm.lon], { icon: fi })
      .addTo(map)
      .bindPopup(`<b>${farm.name}</b><br>${TX.crop}: ${farm.crop}<br>${TX.area}: ${farm.size} acres<br>Status: ${farm.status}`);
  };

  const saveFarm = () => {
    if (!formFarm.name || !formFarm.crop) return;
    const lat  = formFarm.clickedLat || (user.lat || 9.9252)  + (Math.random() - 0.5) * 0.02;
    const lon  = formFarm.clickedLon || (user.lon || 78.1198) + (Math.random() - 0.5) * 0.02;
    const farm = { id: Date.now(), ...formFarm, lat, lon, addedOn: new Date().toLocaleDateString("en-IN") };
    const updated = [...farms, farm];
    setFarms(updated);

    // Persist
    const users = S.get("users") || [];
    const idx   = users.findIndex(u => u.id === user.id);
    if (idx >= 0) { users[idx].farms = updated; S.set("users", users); S.set("current_user", users[idx]); }

    // Add marker to live map
    if (mapInstance.current && window.L) addFarmMarker(window.L, mapInstance.current, farm);

    setAddMode(false);
    setFormFarm({ name: "", crop: "", size: "", soilType: "Red", status: "Healthy" });
  };

  const statusColor = { Healthy: C.bg2, "Disease Alert": C.red, Monitor: C.orange };
  const statusBg    = { Healthy: C.pale, "Disease Alert": "#fff0f0", Monitor: "#fff8ee" };

  const fieldConditions = [
    { label: TX.temperature, val: "32°C",           risk: "Low"    },
    { label: TX.humidity,    val: "72%",             risk: "Medium" },
    { label: TX.pestRisk,    val: "Moderate",        risk: "Medium" },
    { label: TX.diseaseRisk, val: t("common.error") ? "High" : "High", risk: "High" },
    { label: TX.irrigation,  val: "Tomorrow 6 AM",  risk: ""       },
  ];

  return (
    <div style={{ padding: 20 }}>

      {/* ── Header ───────────────────────────────────────────────────────────── */}
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 16 }}>
        <div>
          <h1 style={{ fontSize: 22, fontWeight: 600, color: C.text, margin: 0 }}>🗺️ {TX.title}</h1>
          <p style={{ color: C.muted, fontSize: 13, margin: "4px 0 0" }}>{TX.subtitle}</p>
        </div>
        <Btn onClick={() => setAddMode(!addMode)} variant={addMode ? "amber" : "primary"}>
          {addMode ? TX.clickMode : TX.addPlot}
        </Btn>
      </div>

      {/* ── Add Farm Form ────────────────────────────────────────────────────── */}
      {addMode && (
        <Card style={{ marginBottom: 12, background: "#fffbeb", border: `1px solid #e0c060` }}>
          <div style={{ fontSize: 13, fontWeight: 600, color: C.amber, marginBottom: 10 }}>📌 {TX.addPlot}</div>
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 10 }}>
            <Input label={TX.farmName} value={formFarm.name}     onChange={e => setFormFarm(p => ({ ...p, name:     e.target.value }))} placeholder="e.g. North Field" />
            <Input label={TX.crop}     value={formFarm.crop}     onChange={e => setFormFarm(p => ({ ...p, crop:     e.target.value }))} options={CROPS_ALL} />
            <Input label={TX.size}     value={formFarm.size}     onChange={e => setFormFarm(p => ({ ...p, size:     e.target.value }))} type="number" placeholder="e.g. 2.5" />
            <Input label={TX.soilType} value={formFarm.soilType} onChange={e => setFormFarm(p => ({ ...p, soilType: e.target.value }))} options={["Red","Black","Loamy","Sandy","Clay","Alluvial"]} />
            <Input label={TX.status}   value={formFarm.status}   onChange={e => setFormFarm(p => ({ ...p, status:   e.target.value }))} options={["Healthy","Disease Alert","Monitor","Harvested","Fallow"]} />
          </div>
          <div style={{ display: "flex", gap: 8, marginTop: 4 }}>
            <Btn onClick={saveFarm} style={{ padding: "8px 20px" }}>✅ {TX.saveFarm}</Btn>
            <Btn variant="ghost" onClick={() => setAddMode(false)} style={{ padding: "8px 20px" }}>{TX.cancel}</Btn>
          </div>
          <div style={{ fontSize: 11.5, color: C.amber, marginTop: 8 }}>{TX.clickTip}</div>
        </Card>
      )}

      {/* ── Map + Sidebar ────────────────────────────────────────────────────── */}
      <div style={{ display: "grid", gridTemplateColumns: "1fr 300px", gap: 14 }}>

        {/* Map */}
        <Card style={{ padding: 0, overflow: "hidden" }}>
          {!loaded && (
            <div style={{ height: 460, display: "flex", alignItems: "center", justifyContent: "center", color: C.muted }}>
              {TX.loading}
            </div>
          )}
          <div ref={mapRef} style={{ height: 460, display: loaded ? "block" : "none" }} />
        </Card>

        {/* Right panel */}
        <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>

          {/* Farm list */}
          <Card style={{ padding: 12 }}>
            <div style={{ fontSize: 12.5, fontWeight: 600, color: C.text, marginBottom: 8 }}>
              {TX.yourFarms} ({farms.length})
            </div>
            {farms.length === 0 && (
              <div style={{ fontSize: 12, color: C.muted, textAlign: "center", padding: "16px 0" }}>
                {TX.noFarms}<br />{TX.addFirst}
              </div>
            )}
            {farms.map(f => (
              <div key={f.id} style={{ padding: "8px 0", borderBottom: `1px solid ${C.border}`, display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                <div>
                  <div style={{ fontSize: 13, fontWeight: 500, color: C.text }}>{f.name}</div>
                  <div style={{ fontSize: 11, color: C.muted }}>{f.crop} • {f.size} {TX.area?.toLowerCase()} • {f.soilType}</div>
                  <div style={{ fontSize: 11, color: C.muted }}>{f.addedOn}</div>
                </div>
                <Badge color={statusColor[f.status] || C.muted} bg={statusBg[f.status] || C.pale}>
                  {f.status}
                </Badge>
              </div>
            ))}
          </Card>

          {/* Field conditions */}
          <Card style={{ padding: 12, background: C.pale }}>
            <div style={{ fontSize: 12.5, fontWeight: 600, color: C.text, marginBottom: 8 }}>
              {TX.fieldConds}
            </div>
            {fieldConditions.map(r => (
              <div key={r.label} style={{ display: "flex", justifyContent: "space-between", marginBottom: 6, fontSize: 12.5 }}>
                <span style={{ color: C.muted }}>{r.label}</span>
                <span style={{ fontWeight: 500, color: r.risk === "High" ? C.red : r.risk === "Medium" ? C.orange : C.text }}>
                  {r.val}
                </span>
              </div>
            ))}
          </Card>

          {/* NDVI */}
          <Card style={{ padding: 12, background: "linear-gradient(135deg,#0e3a1c,#062010)", border: "none" }}>
            <div style={{ fontSize: 13, fontWeight: 600, color: "#fff", marginBottom: 6 }}>{TX.ndvi}</div>
            <div style={{ fontSize: 12, color: "rgba(255,255,255,0.7)", lineHeight: 1.6 }}>
              {t("common.loading") ? "" : ""}Crop health index:{" "}
              <span style={{ color: "#5de87a", fontWeight: 600 }}>0.72 (Good)</span><br />
              Last satellite pass: Today 10:32 AM<br />
              Cloud cover: 18%
            </div>
            <div style={{ marginTop: 10, display: "flex", gap: 6 }}>
              {[{ c: "#1a7a3a", l: t("common.yes") ? "Healthy" : "Healthy" }, { c: "#c87010", l: "Stress" }, { c: "#b83232", l: "Alert" }].map(s => (
                <div key={s.l} style={{ display: "flex", alignItems: "center", gap: 4, fontSize: 10.5, color: "rgba(255,255,255,0.6)" }}>
                  <div style={{ width: 8, height: 8, borderRadius: 2, background: s.c }} />
                  {s.l}
                </div>
              ))}
            </div>
          </Card>
        </div>
      </div>
    </div>
  );
}

export default FarmMap;
